  "content.research.res_lora_peft.technicalLore": "Enables model fine-tuning on consumer hardware without modifying the full weight tensor W = W0 + B*A.",
  "content.research.res_lora_peft.title": "Low-Rank Adaptation (LoRA & QLoRA)",
  "content.research.res_mamba_ssm.effectDescription": "Unlocks linear-time sequence modeling with selective memory dynamics for massive contexts.",
  "content.research.res_mamba_ssm.technicalLore": "Selective scan mechanisms allowing data-dependent state transitions with hardware-efficient hardware mapping.",
  "content.research.res_mamba_ssm.title": "Selective State Space Models (Mamba Architecture)",
