  "content.research.res_moe_architecture.technicalLore": "Softmax Top-K gating router with auxiliary load-balancing loss preventing expert saturation.",
  "content.research.res_moe_architecture.title": "Sparse Mixture of Experts Architecture (Sparse MoE)",
  "content.research.res_multimodal_diffusion.effectDescription": "Enables generative multimodal perception across image, audio, and sensor arrays.",
  "content.research.res_multimodal_diffusion.technicalLore": "Cross-attention conditioned denoising diffusion probabilistic models operating in compact latent spaces.",
  "content.research.res_multimodal_diffusion.title": "Multimodal Latent Diffusion Models",
