  "content.research.res_recursive_self_code.technicalLore": "Live weight recompilation and neural architecture search (NAS) controlled by recursive cybernetic feedback.",
  "content.research.res_recursive_self_code.title": "Recursive Computational Graph Self-Modification",
  "content.research.res_rlhf_training.effectDescription": "Enables policy optimization guided by reward models and preference rankings.",
  "content.research.res_rlhf_training.technicalLore": "PPO-based policy gradient updates constrained by KL-divergence penalties from the base model.",
  "content.research.res_rlhf_training.title": "Reinforcement Learning from Human Feedback (RLHF)",
  "content.research.res_rope_embeddings.effectDescription": "Extends effective context window up to 128,000 tokens without perplexity degradation.",
  "content.research.res_rope_embeddings.technicalLore": "Applies complex rotation matrix to paired vector components based on relative token positions.",
  "content.research.res_rope_embeddings.title": "Rotary Position Embeddings (RoPE) & Infinite Window",
